-- ================================================================================================
-- Notification.dbo.notificationLog
--
-- Holds a record of all alerts generated by SQLBeat. It is from this table that email messages are
-- generated to be sent, based on messageRules.
-- ================================================================================================
/****** Object:  Table [dbo].[notificationLog]    Script Date: 11/6/2026 9:52:52 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TABLE [dbo].[notificationLog](
	[ukey] [int] IDENTITY(1,1) NOT NULL,	-- An internally used incrementing identity counter; uniquely identifies this row, and may be used as a Foreign Key.
	[ymd] [datetime] NULL,	-- The date of the alert
	[subject] [varchar](300) NULL,	-- This is the subject of the alert message, and the field which is used to identify whether a new staged message already exists and is duplicate
	[message] [varchar](8000) NULL,	-- This is the body of the alert message
	[messageSent] [bit] NULL,	-- This field has been deprecated
	[messageSentDate] [datetime] NULL,	-- This field has been deprecated
	[severity] [int] NULL,	-- This is the severity (1,2 or 3) of the message. A severity of 1 will be a critical message. A severity of 3 will be informational only.
	[isJobFailure] [bit] NULL,	-- When this bit is set, this is an alert about a failing job
	[isLogShippingJobFailure] [bit] NULL,	-- When this bit is set, this is an alert about a failing log shipping job
	[isLongRunningJob] [bit] NULL,	-- When this bit is set, this is an alert about a long running job
	[isBlocking] [bit] NULL,	-- When this bit is set, this is an alert about Blocking
	[isLongRunningProcess] [bit] NULL,	-- When this bit is set, this is an alert about a long running sql process
	[isDriveSpace] [bit] NULL,	-- When this bit is set, this is an alert about Drive Space
	[isLogSize] [bit] NULL,	-- When this bit is set, this is an alert about SQL LDF file size
	[isEventLog] [bit] NULL,	-- When this bit is set, this is an alert from the Event Log Monitor module
	[serverName] [varchar](100) NULL,	-- The server name
	[isService] [bit] NULL,	-- When this bit is set, this is an alert about Services
	[isConnectivity] [bit] NULL,	-- When this bit is set, this is an alert about Connectivity (sql or server)
	[isConfiguration] [bit] NULL,	-- When this bit is set, this is an alert from the WMI Monitor module
	[isInstalledSoftware] [bit] NULL,	-- When this bit is set, this is an alert from the Installed Software Monitor module
	[isMonitorMessage] [bit] NULL	-- When this bit is set, this is an alert about SQLBeat
) ON [PRIMARY]
GO
